p = 998244353

def bsgs(g, h):
    '''
    Solve for x in h = g^x mod p given a prime p.
    '''
    N = ceil(sqrt(p - 1))  # phi(p) is p-1 if p is prime

    # Store hashmap of g^{1...m} (mod p). Baby step.
    tbl = {pow(g, i, p): i for i in range(N)}

    # Precompute via Fermat's Little Theorem
    c = pow(g, N * (p - 2), p)

    # Search for an equivalence in the table. Giant step.
    for j in range(N):
        y = (h * pow(c, j, p)) % p
        if y in tbl:
            return j * N + tbl[y]

def gcd(a, b):
    return b if a % b == 0 else gcd(b, a % b)

def xgcd(a, b):
    """return (g, x, y) such that a*x + b*y = g = gcd(x, y)"""
    x0, x1, y0, y1 = 0, 1, 1, 0
    while a != 0:
        q, b, a = b // a, a, b % a
        y0, y1 = y1, y0 - q * y1
        x0, x1 = x1, x0 - q * x1
    return b, x0, y0

def inv(a, m):
    g, x, y = xgcd(a, m)
    if g != 1:
        return None
    return (x + m) % m

# solve a = bx (mod m)
def div(a, b, m):
    k = gcd(b, m)
    if a % k != 0:
        return None

    ak = a // k
    bk = b // k
    mk = m // k
    inv_bk = inv(bk, mk)
    return (ak * inv_bk) % mk

