            optimized = get_optimized_lists(lists)
            if optimized is None:
                print("-1")
            else:
                print("{}".format(len(optimized)))
                for l in optimized:
                    print("{}".format(l))
        except:
            traceback.print_exc(file=sys.stdout)
            print('get_min_dist failed')

