	if bit < 0: return 0
	l = []
	r = []
	for el in nums:
		if ((el >> bit) & 1): r.append(el)
		else: l.append(el)
	if len(l) == 0: return solve(r, bit - 1)
	if len(r) == 0: return solve(l, bit - 1)
	return min(solve(l, bit - 1), solve(r, bit - 1)) + (1 << bit)
