N = int(input())

number = list(map(int, input().split()))

seq = []
ans = []

l = 0
r = N-1

def correct(ans, l, r, action):
    for i in range(len(ans)-1, -1, -1):
        if not ans[i] == 'X':
            break
        ans[i] = action
        if action == 'L':
            r += 1
        else:
            l -= 1
    return l, r

def run(number, l, r, seq):
    ans = []
    while l <= r:
        n1 = number[l]
        n2 = number[r]

        if n1 == n2:
            if seq and n1 <= seq[-1]:
                break

            steps = 0
            last = -1
            if seq:
                last = seq[-1]
            while l+steps <= r-steps and number[l+steps] == number[r-steps] and number[l+steps] > last:
                seq.append(number[l+steps])
                ans.append('X')
                last = number[l+steps]
                steps += 1

            s1 = run(number, l+steps, r, [seq[-1]])
            s2 = run(number, l, r-steps, [seq[-1]])
            if len(s1) > len(s2):
                return ''.join(ans).replace('X', 'L') + s1
            else:
                return ''.join(ans).replace('X', 'R') + s2
        elif not seq:
            if n1 < n2:
                seq.append(n1)
                ans.append('L')
                l += 1
            else:
                seq.append(n2)
                ans.append('R')
                r -= 1
        else:
            last = seq[-1]
            if last < n1 < n2 or n2 <= last < n1:
                l, r = correct(ans, l, r, 'L')
                seq.append(n1)
                ans.append('L')
                l += 1
            elif last < n2 < n1 or n1 <= last < n2:
                l, r = correct(ans, l, r, 'R')
                seq.append(n2)
                ans.append('R')
                r -= 1
            else:
                break
    return ''.join(ans)

