    return "Unhandled Exception"


def multisplit(string):
    """splits at a bracket, comma, quote, or text"""
    """does not split within quotes."""
    parsedstring = []
    curstring = []
    insidequotes = False
    for i in string:

        if insidequotes:
            if i == '"':
                insidequotes = False
                parsedstring.append("".join(curstring))
                curstring = []
            else:
                curstring.append(i)

        elif i in ("(", ")", ",", " "):
            if curstring:
                parsedstring.append("".join(curstring))
            curstring = []

        elif i == '"':
            insidequotes = True
            if curstring:
                parsedstring.append("".join(curstring))
            curstring = []

        else:
            curstring.append(i)

    if curstring:
        parsedstring.append("".join(curstring))
    return parsedstring


