        tmp = [0] * 2
        if v < nv:
            tmp[0] = recur(nv, max(s, v + 1), nv - 1, k - 1)
            tmp[1] = recur(nv, nv + 1, e, k - 1)
        else:
            tmp[0] = recur(nv, s, nv - 1, k - 1)
            tmp[1] = recur(nv, nv + 1, min(v - 1, e), k - 1)
        # print(v, nv, tmp)
        if min(tmp) + cost[(v, nv)] < ret:
            ret = min(tmp) + cost[(v, nv)]
    return ret


