def rotate(puzzle):
    n_puzzle = []
    for y in range(len(puzzle) - 1, -1, -1):
        n_puzzle.append(puzzle[y])
    result = []
    for x in range(len(puzzle[0])):
        col = []
        for y in range(len(puzzle)):
            col.append(n_puzzle[y][x])
        result.append(col)
    return result


def puzzle_match(p1, p2):
    r1 = p2
    r2 = rotate(p2)
    r3 = rotate(r2)
    r4 = rotate(r3)
    variants = [r1, r2, r3, r4]
    return p1 in variants


