def us_num(nums):
  where = None
  for idx, (a, na) in enumerate(zip(nums[:-1], nums[1:])):
    if a > na:
      if where is None:
        where = idx
      else:
        return -1
  if where is None:
    return 0
  elif nums[-1] > nums[0]:
    return -1
  return len(nums) - 1 - where

